const refreshHotScores = `-- name: RefreshHotScores :exec
UPDATE posts SET hot_score = (like_count + 2.0 * comment_count + 3.0 * repost_count)
    / power(extract(epoch FROM (now() - created_at)) / 3600.0 + 2, 1.5)
WHERE deleted_at IS NULL AND visibility = 'public' AND group_id IS NULL
`

func (q *Queries) RefreshHotScores(ctx context.Context) error {
	_, err := q.db.Exec(ctx, refreshHotScores)
	return err
}

const upsertTag = `-- name: UpsertTag :one
INSERT INTO tags (name, slug) VALUES ($1, $2)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name
RETURNING id, name, slug, use_count, created_at
`

type UpsertTagParams struct {
	Name string `json:"name"`
	Slug string `json:"slug"`
}

func (q *Queries) UpsertTag(ctx context.Context, arg UpsertTagParams) (Tag, error) {
	row := q.db.QueryRow(ctx, upsertTag, arg.Name, arg.Slug)
	var i Tag
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.UseCount,
		&i.CreatedAt,
	)
	return i, err
}
